168	std::shared_ptr<Tensor> Tensor::Wrap(ExternalBuffer &buffer, std::optional<nvcv::TensorLayout> layout)
169	{
170	    const DLTensor &dlTensor = buffer.dlTensor();
171	
172	    nvcv::TensorDataStridedCuda data{FillNVCVTensorDataCUDA(dlTensor, std::move(layout))};
173	
174	    // This is the key of a tensor wrapper.
175	    // All tensor wrappers have the same key.
176	    Tensor::Key key;
177	    // We take this opportunity to remove from cache all wrappers that aren't
178	    // being used. They aren't reusable anyway.
179	    Cache::Instance().removeAllNotInUseMatching(key);
180	
181	    auto tensor = std::shared_ptr<Tensor>( // NOSONAR: constructor is private.
182	        new Tensor(data, py::cast(buffer.shared_from_this())));
183	
184	    // Seed the tensor's Resource state with the producer's CUDA stream so the
185	    // first cvcuda op that reads this tensor inserts the necessary
186	    // cross-stream wait.  Skipped when the producer advertised
187	    // `stream: None` / `stream: -1`, which means they've already synchronized.
188	    if (!buffer.producerIsSynced() && buffer.producerStream() != nullptr)
189	    {
190	        int device = buffer.producerDevice();
191	        if (device < 0)
192	        {
193	            util::CheckThrow(cudaGetDevice(&device));
194	        }
195	        tensor->seedLastStream(buffer.producerStream(), device);
196	    }
197	
198	    // Need to add wrappers to cache so that they don't get destroyed by
199	    // the cuda stream when they're last used, and python script isn't
200	    // holding a reference to them. If we don't do it, things might break.
201	    Cache::Instance().add(*tensor);
202	    return tensor;
203	}
