466	// Installed directly as tp_hash: dict/set operations then skip the Python
467	// method-dispatch of a def("__hash__"), which costs several times the hash
468	// itself on this hot path.
469	static Py_hash_t TensorLayoutTpHash(PyObject *self)
470	{
471	    try
472	    {
473	        return TensorLayoutHashValue(py::cast<nvcv::TensorLayout &>(py::handle(self)));
474	    }
475	    catch (const std::exception &e) // NOSONAR: tp_hash is a C slot; no C++ exception may reach CPython
476	    {
477	        PyErr_SetString(PyExc_TypeError, e.what());
478	        return -1;
479	    }
480	}
481	
482	void ExportTensorLayout(py::module &m)
483	{
484	    auto cls = py::class_<nvcv::TensorLayout>(m, "TensorLayout");
485	    cls.def(py::init<const char *>())
486	        .def(
487	            "__eq__", [](const nvcv::TensorLayout &a, const nvcv::TensorLayout &b) { return a == b; },
488	            py::is_operator(), "Check if two TensorLayout objects are equal.")
489	        .def(
490	            "__ne__", [](const nvcv::TensorLayout &a, const nvcv::TensorLayout &b) { return a != b; },
491	            py::is_operator(), "Check if two TensorLayout objects are not equal.")
492	        // Kept alongside the tp_hash slot so TensorLayout.__hash__ resolves to
493	        // the same value; without a def, pybind11 nulls __hash__ once __eq__
494	        // is defined, leaving TensorLayout unhashable.
495	        .def(
496	            "__hash__", [](const nvcv::TensorLayout &l) { return TensorLayoutHashValue(l); },
497	            "Return a value-based hash so TensorLayout can be used as a dict key or set member.")
498	        .def("__repr__", &TensorLayoutToString, "Return the string representation of the TensorLayout object.");
499	
500	    // The class constants are the interned instances themselves (not
501	    // per-access getters), so `TensorLayout.NHWC is tensor.layout` holds.
502	    auto intern = [&cls](const char *name, const nvcv::TensorLayout &layout)
503	    {
504	        py::object obj = py::cast(layout);
505	        InternedTensorLayouts().try_emplace(std::string(TensorLayoutLabels(layout)), obj);
506	        cls.attr(name) = obj;
507	    };
508	    cls.attr("NONE") = py::cast(nvcv::TENSOR_NONE);
509	#define NVCV_DETAIL_DEF_TLAYOUT(LAYOUT) intern(#LAYOUT, nvcv::TENSOR_##LAYOUT);
510	#include <nvcv/TensorLayoutDef.inc> // NOSONAR: this include expands TensorLayout constants inside the binding chain.
511	#undef NVCV_DETAIL_DEF_TLAYOUT
512	
513	    // Override last: pybind's def("__hash__") above set tp_hash to CPython's
514	    // slot dispatcher; replace it with the direct C implementation.
515	    auto *tp    = reinterpret_cast<PyTypeObject *>(cls.ptr());
516	    tp->tp_hash = &TensorLayoutTpHash;
517	    PyType_Modified(tp);
518	
519	    py::implicitly_convertible<py::str, nvcv::TensorLayout>();
520	}
521	
522	void Tensor::Export(py::module &m)
523	{
524	    using namespace py::literals;
525	
526	    py::class_<Tensor, std::shared_ptr<Tensor>, Container>(m, "Tensor", "Tensor")
527	        .def(py::init(&Tensor::CreateForImageBatch), "nimages"_a, "imgsize"_a, "format"_a, "rowalign"_a = 0,
528	             "Create a Tensor object for an ImageBatch.")
529	        .def(py::init(&Tensor::Create), "shape"_a, "dtype"_a, "layout"_a = std::nullopt, "rowalign"_a = 0,
530	             "Create a Tensor object with the given shape, data type and layout.")
531	        .def_property_readonly(
532	            "layout", [](const Tensor &self) { return PyTensorLayout(self.layout()); },
533	            "The TensorLayout of the Tensor.")
534	        .def_property_readonly("shape", &Tensor::shape, "The shape of the Tensor.")
535	        .def_property_readonly("dtype", &Tensor::dtype, "The data type of the Tensor.")
536	        // numpy and others use ndim, let's be consistent with them in python.
537	        // It's not a requirement to be consistent between NVCV Python and C/C++.
538	        // Each language use whatever is appropriate (and expected) in their environment.
539	        .def_property_readonly("ndim", &Tensor::rank, "The number of dimensions of the Tensor.")
540	        .def("cuda", ::cvcudapy::NvtxTrace("cvcuda.Tensor.cuda", &Tensor::cuda),
541	             "Reference to the Tensor on the CUDA device.")
542	        .def("reshape", &Tensor::Reshape, "shape"_a, "layout"_a = std::nullopt,
543	             "Produces a tensor pointing to the same data but with a new shape and layout.")
544	        .def("__repr__", &util::ToString<Tensor>, "Return the string representation of the Tensor object.");
